"""FM-16AB: final two Cartesian-component pathways."""
import sympy as s
from calibration_bank import LEVELS,L
I=s.I
PATHS={'identify-components':'CPX.parts.identify','standard-cartesian':'CPX.parts.standard-form'}
RATIONALES={
'identify-components':['Identify signed coefficients in a real expression.','Distinguish the imaginary coefficient from the imaginary term and recognize a missing part.','Extract parts after collecting signed terms.','Compare components of a parameter-dependent product.','Infer unknown real parameters from component constraints and prove uniqueness.','Classify equality of absolute component magnitudes with four solutions and justify signs and completeness.'],
'standard-cartesian':['Reduce powers of the imaginary unit.','Diagnose incorrect conversion of a negative square root.','Simplify a quotient into real plus imaginary form.','Combine two complex fractions before extracting Cartesian form.','Rationalise a squared quotient and verify its modulus independently.','Enrichment: express a parametric quotient in Cartesian form and classify its inverse real-component constraints, including unattained endpoints.']}
def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown cell')
 a,b,d=map(s.Integer,(v+1,v+3,3*v+5));z=a-b*I;w=d+a*I
 if path=='identify-components':
  if l==1:
   q=f'In the real expression {a}-{b}u, identify the constant and the signed coefficient of u.';f=[a,-b];ans=f'Constant {a}; coefficient {-b}.';steps=['Read the term independent of u and the signed multiplier of u.',ans];hint=['Include the minus sign in the coefficient.'];mist='Reporting the unsigned coefficient.'
  elif l==2:
   q=f'A student says the imaginary part of {-b}i is {-b}i and its real part is undefined. Correct both statements and explain.';f=[0,-b];ans=f'Real part 0; imaginary part {-b}.';steps=['In Cartesian form a+bi, both a and b are real numbers.',f'The real term is absent, so its coefficient is zero; the coefficient of i is {-b}, not {-b}i.'];hint=['The imaginary part is a real coefficient.'];mist='Confusing the imaginary part with the imaginary term.'
  elif l==3:
   q=f'Find the real and imaginary parts of ({L(z)})-({L(w)})+{b}i.';R=a-d;J=-a;f=[R,J];ans=f'Real part {R}; imaginary part {J}.';steps=['Distribute the subtraction over both terms of the second bracket.',f'Collect real terms to give {a}-{d}={R}; imaginary coefficients give {-b}-{a}+{b}={J}.'];hint=['Collect signed coefficients separately.'];mist='Negating only the real part of the second bracket.'
  elif l==4:
   q=f'For real t, find the real and imaginary parts of ({L(a+I*b)})(t-{a}i), then find the t for which the parts are equal.';t=s.Symbol('t',real=True);R=a*t+a*b;J=b*t-a*a;T=(a*b+a*a)/(b-a);f=[R,J,T];ans=f'Real part {L(R)}; imaginary part {L(J)}; t={L(T)}.';steps=[f'Expand and use i squared = -1: the real part is {L(R)} and the imaginary coefficient is {L(J)}.',f'Equate them: ({b}-{a})t={a*b+a*a}.',f'The coefficient {b-a} is nonzero, giving the unique t={L(T)}.'];hint=['Equate the coefficients, not the real term and imaginary term.'];mist='Equating a real number to a multiple of i.'
  elif l==5:
   q=f'For real p,q, let Z=({L(a+b*I)})(p+qi). Given that Re(Z)={a*a-b*d} and Im(Z)={b*a+a*d}, recover p and q and prove uniqueness.';f=[a,d,a*a+b*b];ans=f'p={a}, q={d}.';steps=[f'Expansion gives Re(Z)={a}p-{b}q and Im(Z)={b}p+{a}q.',f'Equate the two coefficients to the given values and eliminate q by multiplying the first equation by {a}, the second by {b}, then adding.',f'The resulting coefficient of p is {a*a+b*b}, nonzero, so p={a}.',f'Back-substitution gives q={d}; both equations hold, proving existence and uniqueness.'];hint=['Eliminate one real unknown using both component equations.'];mist='Treating a single component condition as sufficient.'
  else:
   m=a;B=m*(m+1);t=s.Symbol('t',real=True);U=t-d;R=U**2-B;J=U;rr=[d-m-1,d-m,d+m,d+m+1];ans=f't={rr[0]}, {rr[1]}, {rr[2]}, {rr[3]}; component signs (real, imaginary) respectively (+,-), (-,-), (-,+), (+,+).';f=[*rr,1,-1,-1,-1,-1,1,1,1];steps=[f'Put u=t-{d}. The real part is u squared minus {B} and the imaginary part is u.',f'With r=|u|, equality of magnitudes requires |r squared minus {B}|=r, so r squared minus {B} equals either r or -r.',f'For the first sign, factor (r-{m+1})(r+{m})=0; only r={m+1} is nonnegative.',f'For the second sign, factor (r-{m})(r+{m+1})=0; only r={m} is nonnegative.',f'Both radii are positive and distinct, so u has four values. Recover t by adding {d}.',ans,f'At r={m} the real part is negative; at r={m+1} it is positive. The imaginary part has the sign of u. Both sign cases were exhausted.'];hint=['Replace the absolute imaginary coefficient with a nonnegative variable.','Split the absolute real coefficient into two signed equations.'];mist='Retaining only the equation Re(Z)=Im(Z), or accepting negative radii.';q=f'For real t let $Z=(t-{d})^2-{B}+(t-{d})i$. Determine every t for which |Re(Z)|=|Im(Z)|, and give the signs of both components at each solution. Prove completeness.'
 else:
  if l==1:
   q=f'Simplify i raised to the power {4*v+2} and i raised to the power {4*v+3}.';f=[-1,-I];ans='$-1$ and $-i$.';steps=['Powers of i repeat every four because i to the fourth power is 1.',ans];hint=['Reduce each exponent modulo four.'];mist='Assuming every even power is positive.'
  elif l==2:
   q=f'A student writes the two roots of u squared = {-b*b} as {b} and {-b}. Correct the roots and explain how they are expressed in Cartesian form.';f=[b*I,-b*I];ans=f'{L(b*I)} and {L(-b*I)}.';steps=[f'The squares of the proposed real roots are positive {b*b}, not {-b*b}.',f'Using i squared = -1 gives the two roots {ans} Both have real part zero.'];hint=['Square the proposed roots to test them.'];mist='Dropping i when taking a square root of a negative real number.'
  elif l==3:
   q=f'Write the quotient ({L(z)})/({L(w)}) in standard Cartesian form with exact real coefficients.';N=s.expand(z*s.conjugate(w));D=d*d+a*a;Z=s.expand(N/D);f=[s.re(Z),s.im(Z)];ans=L(Z);steps=[f'Multiply numerator and denominator by {L(s.conjugate(w))}.',f'The expanded numerator is {L(N)} and the real denominator is {D}.',f'Divide each component by {D} to obtain {ans}.'];hint=['Use the denominator conjugate.'];mist='Dividing real and imaginary coefficients separately by the original denominator.'
  elif l==4:
   q=f'Express the sum of 1/({L(z)}) and 1/({L(s.conjugate(z))}) plus {a}i in Cartesian form.';R=2*a/(a*a+b*b);f=[R,a];ans=L(R+a*I);steps=[f'Combine the fractions over the conjugate product {a*a+b*b}.',f'The numerator is the sum of the conjugates, {2*a}, so the fraction sum is purely real.',f'Add {a}i to obtain {ans}.'];hint=['Use a common denominator before simplifying.'];mist='Adding denominators or losing the remaining imaginary term.'
  elif l==5:
   q=f'Write the square of the quotient ({L(z)})/({L(w)}) in exact Cartesian form. Verify its modulus using the moduli of the original numbers.';N=s.expand(z*s.conjugate(w));D=d*d+a*a;Z=s.expand(N**2/D**2);M=(a*a+b*b)/D;f=[s.re(Z),s.im(Z),M];ans=f'{L(Z)}; modulus {L(M)}.';steps=[f'Rationalise the quotient to {L(s.expand(N/D))}.',f'Square the numerator to obtain {L(s.expand(N**2))} and the denominator to obtain {D**2}.',f'Thus the Cartesian result is {L(Z)}.',f'The modulus of a squared quotient is the ratio of the original squared moduli, {L(M)}. Squaring and adding the Cartesian components gives {L(M*M)}, confirming the same modulus.'];hint=['Rationalise before squaring.','Compare squared moduli to avoid unnecessary radicals.'];mist='Squaring real and imaginary terms without the cross term.'
  else:
   t,h=s.symbols('t h',real=True);u=t-a;D=u*u+b*b;R=(u*u-b*b)/D;J=2*b*u/D;radius=b*s.sqrt((1+h)/(1-h));f=[R,J,a,-1,1,s.simplify(radius**2),1-h*h];q=f'For real t, put Z=((t-{a})+{b}i)/((t-{a})-{b}i). Express Z in Cartesian form. For each real h, find every t such that Re(Z)=h and give the corresponding imaginary components. Justify all endpoints.';ans=f'Re(Z)={L(R)}, Im(Z)={L(J)}. h=-1: t={a}, Im(Z)=0. -1<h<1: t={a} plus or minus {L(radius)}, Im(Z)=plus or minus {L(s.sqrt(1-h*h))} with matching signs. Otherwise no solution.';steps=[f'The denominator never vanishes because its imaginary coefficient is {-b}. Multiply by its conjugate to give numerator {L(s.expand((u+b*I)**2))} over {L(D)}.',f'The resulting real and imaginary components are {L(R)} and {L(J)}.',f'Writing u=t-{a}, the real-part equation rearranges to (1-h)u squared=(1+h){b*b}. At h=1 it is impossible; h=-1 forces u=0.',f'For h outside [-1,1], the ratio (1+h)/(1-h) is negative, hence no real u. For -1<h<1 there are exactly two values u=plus or minus {L(radius)}.',f'The quotient has modulus one because numerator and denominator are conjugates. Hence the imaginary component has magnitude {L(s.sqrt(1-h*h))}; its sign is that of u because {b}>0. At h=-1 it is zero.','All transformations were reversible on the original domain, and all real h cases have been covered.'];hint=['Multiply numerator and denominator by the conjugate.','Isolate the square of t minus the shift before dividing by 1-h.'];mist='Including h=1 as an attained value or dropping the negative square-root branch.'
 return dict(path=path,focus_skill=PATHS[path],tier=l,variant=v,assessment_role='prerequisite_bridge' if l==1 else 'concept_diagnostic' if l==2 else 'direct_focus_task',question_latex=q,final_answer_latex=ans,worked_solution_latex=steps,progressive_hints=hint,rubric=[dict(marks=1,criterion=e) for e in steps],facts=[str(e) for e in f],likely_mistake=mist,origin='original',examination_source=None,difficulty_status='editorial_design_teacher_pending',demand_rationale=RATIONALES[path][l-1])
